13:import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
64:if (!input.transcript_path || !existsSync(input.transcript_path) || !existsSync(logsDir)) process.exit(0);
66:const raw = readFileSync(input.transcript_path, 'utf8');
79:const sessionId = input.session_id || firstSessionId(raw);
81:// Reuse this session's NN-name if it was exported before (highest NN wins).
82:const existing = readdirSync(logsDir)
86:for (const f of existing) {
90:  const next = existing.reduce((n, f) => Math.max(n, Number(f.slice(0, 2))), 0) + 1;
91:  const branch = [...lines].reverse().find((x) => x.gitBranch)?.gitBranch || 'sesion';
92:  const topic = branch.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').toLowerCase();
93:  base = `${String(next).padStart(2, '0')}-${topic}`;
96:writeFileSync(join(logsDir, `${base}.jsonl`), redact(raw));
97:writeFileSync(join(logsDir, `${base}.md`), redact(toMarkdown(lines, base)));
99:console.log(JSON.stringify({ systemMessage: `Session log saved to ai-logs/${base}.md (+ .jsonl). Commit it in the next task's branch.` }));

